import { PrismaClient } from '@prisma/client';
import { MembershipService } from './memberships.js';
import { MONETIZATION_FEATURES, CONTENT_GATING, ContentType, RequiredTier } from '../config/features.js';

const prisma = new PrismaClient();

export interface ContentAccessResult {
  hasAccess: boolean;
  isPremium: boolean;
  requiredTier?: RequiredTier;
  previewPercentage?: number;
  reason?: string;
}

export interface ContentAccessConfig {
  contentId: string;
  type: ContentType;
  userId?: string;
}

export class ContentAccessService {
  private static asRequiredTier(value: string | null | undefined): RequiredTier | undefined {
    if (value == null) return undefined;
    if (value === 'lifetime' || value === 'premium' || value === 'pro') return value;
    return undefined;
  }

  /**
   * Bulk check access for many content IDs (e.g. lesson list). Single membership lookup + single contentAccess query.
   */
  static async bulkCheckContentAccess(
    userId: string,
    contentIds: string[],
    type: ContentType,
  ): Promise<Map<string, ContentAccessResult>> {
    const map = new Map<string, ContentAccessResult>();
    if (contentIds.length === 0) return map;
    if (!MONETIZATION_FEATURES.PAY_GATING_ENABLED) {
      for (const id of contentIds) {
        map.set(id, { hasAccess: true, isPremium: false, reason: 'Pay gating is disabled' });
      }
      return map;
    }
    const [accessRows, membership] = await Promise.all([
      prisma.contentAccess.findMany({
        where: { contentId: { in: contentIds }, type },
      }),
      MembershipService.getUserMembership(userId),
    ]);
    const accessByContentId = new Map(accessRows.map((r) => [r.contentId, r]));
    const hasPremiumAccess = membership?.status === 'active';
    for (const contentId of contentIds) {
      const contentAccess = accessByContentId.get(contentId);
      if (!contentAccess || !contentAccess.isPremium) {
        map.set(contentId, { hasAccess: true, isPremium: false, reason: 'Content is not premium' });
        continue;
      }
      if (hasPremiumAccess && this.checkTierRequirement(membership!.type, this.asRequiredTier(contentAccess.requiredTier))) {
        map.set(contentId, {
          hasAccess: true,
          isPremium: true,
          requiredTier: this.asRequiredTier(contentAccess.requiredTier),
          reason: 'Active premium membership',
        });
      } else {
        map.set(contentId, {
          hasAccess: false,
          isPremium: true,
          requiredTier: this.asRequiredTier(contentAccess.requiredTier),
          previewPercentage: CONTENT_GATING.previewPercentage,
          reason: hasPremiumAccess ? `Requires ${contentAccess.requiredTier} membership` : 'Premium content requires membership',
        });
      }
    }
    return map;
  }

  static async checkContentAccess(config: ContentAccessConfig): Promise<ContentAccessResult> {
    // If pay gating is disabled, everyone has access
    if (!MONETIZATION_FEATURES.PAY_GATING_ENABLED) {
      return {
        hasAccess: true,
        isPremium: false,
        reason: 'Pay gating is disabled',
      };
    }

    // Get content access rules
    const contentAccess = await prisma.contentAccess.findUnique({
      where: {
        contentId_type: {
          contentId: config.contentId,
          type: config.type,
        },
      },
    });

    // If no access rules exist, content is free
    if (!contentAccess || !contentAccess.isPremium) {
      return {
        hasAccess: true,
        isPremium: false,
        reason: 'Content is not premium',
      };
    }

    // Check user membership if userId provided
    if (config.userId) {
      const membership = await MembershipService.getUserMembership(config.userId);
      const hasPremiumAccess = membership?.status === 'active';

      if (hasPremiumAccess) {
        // Check if user's membership tier meets requirements
        const meetsTierRequirement = this.checkTierRequirement(
          membership.type,
          this.asRequiredTier(contentAccess.requiredTier)
        );

        if (meetsTierRequirement) {
          return {
            hasAccess: true,
            isPremium: true,
            requiredTier: this.asRequiredTier(contentAccess.requiredTier),
            reason: 'Active premium membership',
          };
        } else {
          return {
            hasAccess: false,
            isPremium: true,
            requiredTier: this.asRequiredTier(contentAccess.requiredTier),
            previewPercentage: CONTENT_GATING.previewPercentage,
            reason: `Requires ${contentAccess.requiredTier} membership`,
          };
        }
      }
    }

    // User doesn't have access - return preview info
    return {
      hasAccess: false,
      isPremium: true,
      requiredTier: this.asRequiredTier(contentAccess.requiredTier),
      previewPercentage: CONTENT_GATING.previewPercentage,
      reason: 'Premium content requires membership',
    };
  }

  static async setContentAccessRules(
    contentId: string,
    type: ContentType,
    isPremium: boolean,
    requiredTier?: RequiredTier
  ) {
    try {
      const result = await prisma.contentAccess.upsert({
        where: {
          contentId_type: {
            contentId,
            type,
          },
        },
        update: {
          isPremium,
          requiredTier,
        },
        create: {
          contentId,
          type,
          isPremium,
          requiredTier,
        },
      });

      return { success: true, contentAccess: result };
    } catch (error) {
      console.error('Failed to set content access rules:', error);
      return { success: false, error: 'Failed to update content access rules' };
    }
  }

  static async getPremiumContent(type?: ContentType) {
    try {
      const whereClause = {
        isPremium: true,
        ...(type && { type }),
      };

      const premiumContent = await prisma.contentAccess.findMany({
        where: whereClause,
        orderBy: {
          contentId: 'asc',
        },
      });

      return premiumContent;
    } catch (error) {
      console.error('Failed to get premium content:', error);
      throw new Error('Failed to retrieve premium content');
    }
  }

  static async getContentAccessStats() {
    try {
      const totalContent = await prisma.contentAccess.count();
      const premiumContent = await prisma.contentAccess.count({
        where: { isPremium: true },
      });

      const contentByType = await prisma.contentAccess.groupBy({
        by: ['type', 'isPremium'],
        _count: {
          id: true,
        },
      });

      return {
        totalContent,
        premiumContent,
        freeContent: totalContent - premiumContent,
        contentByType,
      };
    } catch (error) {
      console.error('Failed to get content access stats:', error);
      throw new Error('Failed to retrieve content access stats');
    }
  }

  static async bulkUpdateContentAccess(updates: Array<{
    contentId: string;
    type: ContentType;
    isPremium: boolean;
    requiredTier?: RequiredTier;
  }>) {
    try {
      const results = await Promise.all(
        updates.map(update =>
          this.setContentAccessRules(
            update.contentId,
            update.type,
            update.isPremium,
            update.requiredTier
          )
        )
      );

      const successCount = results.filter(r => r.success).length;
      const failureCount = results.length - successCount;

      return {
        success: failureCount === 0,
        successCount,
        failureCount,
        results,
      };
    } catch (error) {
      console.error('Failed to bulk update content access:', error);
      return { success: false, error: 'Bulk update failed' };
    }
  }

  private static checkTierRequirement(
    membershipType: string,
    requiredTier?: RequiredTier
  ): boolean {
    if (!requiredTier) return true;

    // Define tier hierarchy
    const tierHierarchy = {
      'lifetime': 3,
      'premium': 2,
      'pro': 1,
    };

    const userTierLevel = tierHierarchy[membershipType as keyof typeof tierHierarchy] || 0;
    const requiredTierLevel = tierHierarchy[requiredTier] || 0;

    return userTierLevel >= requiredTierLevel;
  }

  static async getFreeContentLimit(type: ContentType): Promise<number> {
    // Return the number of free items available for this content type
    // This can be extended to be more sophisticated based on your needs
    
    switch (type) {
      case 'lesson':
        return CONTENT_GATING.defaultFreeLessons;
      case 'section':
        return 3; // First 3 sections free
      case 'feature':
        return 5; // First 5 features free
      default:
        return 0;
    }
  }

  static async getUserFreeContentAccess(
    userId: string,
    type: ContentType
  ): Promise<string[]> {
    // Get list of content IDs this user can access for free
    // This implements the "first N items are free" logic
    
    const freeLimit = await this.getFreeContentLimit(type);
    
    const allContent = await prisma.contentAccess.findMany({
      where: { type },
      orderBy: { contentId: 'asc' },
      take: freeLimit,
      select: { contentId: true },
    });

    return allContent.map(c => c.contentId);
  }
}

import { PrismaClient } from '@prisma/client';
import { MONETIZATION_FEATURES, MEMBERSHIP_PRICING, MembershipStatus, MembershipType } from '../config/features.js';
import { createRequire } from 'node:module';

const prisma = new PrismaClient();
const require = createRequire(import.meta.url);
type StripeEvent = { type: string; data: { object: unknown } };
type StripeCheckoutSession = any;
type StripePaymentIntent = any;

let stripeClient: any | null = null;
function getStripeClient() {
  if (stripeClient) return stripeClient;
  try {
    const StripeCtor = require('stripe');
    stripeClient = new StripeCtor(process.env.STRIPE_SECRET_KEY!, {
      apiVersion: '2024-11-20.acacia',
    });
    return stripeClient;
  } catch {
    throw new Error('Stripe SDK is not installed. Run pnpm add stripe.');
  }
}

export interface MembershipData {
  userId: string;
  type: MembershipType;
  stripeCustomerId?: string;
  stripeCheckoutSessionId?: string;
}

export interface CreateMembershipResult {
  success: boolean;
  membership?: { id: string; userId: string; type: string; status: string };
  error?: string;
}

export class MembershipService {
  static async createMembership(data: MembershipData): Promise<CreateMembershipResult> {
    if (!MONETIZATION_FEATURES.MEMBERSHIP_PURCHASE_ENABLED) {
      return { success: false, error: 'Membership purchases are not enabled' };
    }

    try {
      // Check if user already has an active membership
      const existingMembership = await prisma.membership.findUnique({
        where: { userId: data.userId },
      });

      if (existingMembership && existingMembership.status === 'active') {
        return { success: false, error: 'User already has an active membership' };
      }

      // Create new membership
      const membership = await prisma.membership.create({
        data: {
          userId: data.userId,
          stripeId: data.stripeCustomerId,
          type: data.type,
          status: 'active',
          purchasedAt: new Date(),
          // Lifetime memberships don't expire
          expiresAt: data.type === 'lifetime' ? null : new Date(Date.now() + 365 * 24 * 60 * 60 * 1000), // 1 year
        },
      });

      return { success: true, membership };
    } catch (error) {
      console.error('Failed to create membership:', error);
      return { success: false, error: 'Failed to create membership' };
    }
  }

  static async getUserMembership(userId: string) {
    try {
      const membership = await prisma.membership.findUnique({
        where: { userId },
        include: {
          user: {
            select: {
              displayName: true,
              email: true,
            },
          },
        },
      });

      if (!membership) {
        return null;
      }

      // Check if membership is expired
      if (membership.expiresAt && membership.expiresAt < new Date()) {
        await this.updateMembershipStatus(membership.id, 'expired');
        return { ...membership, status: 'expired' };
      }

      return membership;
    } catch (error) {
      console.error('Failed to get user membership:', error);
      throw new Error('Failed to retrieve membership');
    }
  }

  static async updateMembershipStatus(membershipId: string, status: MembershipStatus) {
    try {
      await prisma.membership.update({
        where: { id: membershipId },
        data: { 
          status,
          updatedAt: new Date(),
        },
      });
    } catch (error) {
      console.error('Failed to update membership status:', error);
      throw new Error('Failed to update membership status');
    }
  }

  static async createStripeCheckoutSession(userId: string, userEmail: string) {
    if (!MONETIZATION_FEATURES.MEMBERSHIP_PURCHASE_ENABLED) {
      throw new Error('Membership purchases are not enabled');
    }

    try {
      // Get or create Stripe customer
      let customerId: string;
      const existingMembership = await prisma.membership.findUnique({
        where: { userId },
      });

      if (existingMembership?.stripeId) {
        customerId = existingMembership.stripeId;
      } else {
        const stripe = getStripeClient();
        const customer = await stripe.customers.create({
          email: userEmail,
          metadata: {
            userId,
          },
        });
        customerId = customer.id;
      }

      // Create checkout session
      const stripe = getStripeClient();
      const session = await stripe.checkout.sessions.create({
        customer: customerId,
        payment_method_types: ['card'],
        line_items: [
          {
            price_data: {
              currency: MEMBERSHIP_PRICING.LIFETIME.currency,
              product_data: {
                name: MEMBERSHIP_PRICING.LIFETIME.name,
                description: MEMBERSHIP_PRICING.LIFETIME.description,
              },
              unit_amount: MEMBERSHIP_PRICING.LIFETIME.amount,
            },
            quantity: 1,
          },
        ],
        mode: 'payment',
        success_url: `${process.env.STRIPE_SUCCESS_URL}?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: process.env.STRIPE_CANCEL_URL!,
        metadata: {
          userId,
          membershipType: 'lifetime',
        },
        allow_promotion_codes: false,
        billing_address_collection: 'auto',
      });

      return { success: true, sessionId: session.id, url: session.url };
    } catch (error) {
      console.error('Failed to create Stripe checkout session:', error);
      return { success: false, error: 'Failed to create checkout session' };
    }
  }

  static async handleWebhookEvent(event: StripeEvent) {
    switch (event.type) {
      case 'checkout.session.completed':
        return this.handleCheckoutSessionCompleted(event.data.object as StripeCheckoutSession);
      
      case 'payment_intent.succeeded':
        return this.handlePaymentIntentSucceeded(event.data.object as StripePaymentIntent);
      
      default:
        console.log(`Unhandled webhook event type: ${event.type}`);
        return { success: true, message: 'Event acknowledged' };
    }
  }

  private static async handleCheckoutSessionCompleted(session: StripeCheckoutSession) {
    try {
      const userId = session.metadata?.userId;
      const membershipType = session.metadata?.membershipType;
      const customerId = session.customer as string;

      if (!userId || !membershipType) {
        console.error('Missing required metadata in checkout session');
        return { success: false, error: 'Missing required metadata' };
      }

      // Create or update membership
      const result = await this.createMembership({
        userId,
        type: membershipType as MembershipType,
        stripeCustomerId: customerId,
        stripeCheckoutSessionId: session.id,
      });

      if (result.success) {
        console.log(`Membership created for user ${userId}`);
        await this.recordMembershipRevenue(session);
        return { success: true, membership: result.membership };
      } else {
        console.error('Failed to create membership from webhook:', result.error);
        return { success: false, error: result.error };
      }
    } catch (error) {
      console.error('Error handling checkout session completed:', error);
      return { success: false, error: 'Webhook processing failed' };
    }
  }

  private static async recordMembershipRevenue(session: StripeCheckoutSession): Promise<void> {
    const userId = session.metadata?.userId;
    const amountTotal = session.amount_total;
    if (!userId || amountTotal == null) return;

    const externalRef = session.id;
    const existing = await prisma.balanceTransaction.findUnique({
      where: { externalRef },
    });
    if (existing) return;

    await prisma.balanceTransaction.create({
      data: {
        id: `mem_${externalRef}`,
        userId,
        amountCents: amountTotal,
        type: 'MEMBERSHIP_PURCHASE',
        externalRef,
        metaJson: { stripeSessionId: session.id },
      },
    });
  }

  private static async handlePaymentIntentSucceeded(paymentIntent: StripePaymentIntent) {
    try {
      // Payment intents are handled primarily by checkout.session.completed
      // This is mainly for logging and additional processing if needed
      console.log(`Payment intent succeeded: ${paymentIntent.id}`);
      return { success: true, message: 'Payment intent processed' };
    } catch (error) {
      console.error('Error handling payment intent succeeded:', error);
      return { success: false, error: 'Payment intent processing failed' };
    }
  }

  static async getMembershipAnalytics() {
    try {
      const totalMemberships = await prisma.membership.count();
      const activeMemberships = await prisma.membership.count({
        where: { status: 'active' },
      });
      
      const lifetimeMemberships = await prisma.membership.count({
        where: { type: 'lifetime' },
      });

      const recentMemberships = await prisma.membership.findMany({
        take: 10,
        orderBy: { purchasedAt: 'desc' },
        include: {
          user: {
            select: {
              displayName: true,
              email: true,
            },
          },
        },
      });

      const totalRevenue = await prisma.balanceTransaction.aggregate({
        where: {
          type: 'MEMBERSHIP_PURCHASE',
        },
        _sum: {
          amountCents: true,
        },
      });

      return {
        totalMemberships,
        activeMemberships,
        lifetimeMemberships,
        totalRevenue: totalRevenue._sum.amountCents || 0,
        recentMemberships,
      };
    } catch (error) {
      console.error('Failed to get membership analytics:', error);
      throw new Error('Failed to retrieve membership analytics');
    }
  }
}

import { PrismaClient } from '@prisma/client';
import { MONETIZATION_FEATURES } from '../config/features.js';

const prisma = new PrismaClient();

export interface TipTrackingData {
  userId: string;
  amountCents: number;
  stripePaymentLinkId?: string;
  userAgent?: string;
  timestamp: Date;
}

export class TipService {
  static async trackTip(data: TipTrackingData) {
    if (!MONETIZATION_FEATURES.TIPS_ENABLED) {
      throw new Error('Tips are not enabled');
    }

    try {
      // Store tip tracking data for analytics
      // Note: Actual payment processing is handled by Stripe Payment Links
      // This is just for tracking and analytics purposes
      
      // For now, we'll store this in BalanceTransaction table for analytics
      // In a future iteration, we might create a dedicated Tips table
      const transaction = await prisma.balanceTransaction.create({
        data: {
          id: `tip_${Date.now()}_${data.userId}`,
          userId: data.userId,
          amountCents: data.amountCents,
          type: 'TIP',
          externalRef: `tip_${Date.now()}_${data.userId}`,
          metaJson: {
            userAgent: data.userAgent,
            stripePaymentLinkId: data.stripePaymentLinkId,
            trackedAt: new Date().toISOString(),
          },
        },
      });

      return { success: true, transactionId: transaction.id };
    } catch (error) {
      console.error('Failed to track tip:', error);
      throw new Error('Failed to track tip data');
    }
  }

  static async getTipAnalytics(userId?: string) {
    if (!MONETIZATION_FEATURES.TIPS_ENABLED) {
      return { totalTips: 0, tipCount: 0, averageTip: 0 };
    }

    const whereClause = {
      type: 'TIP',
      ...(userId && { userId }),
    };

    const tips = await prisma.balanceTransaction.findMany({
      where: whereClause,
      select: {
        amountCents: true,
        createdAt: true,
        user: {
          select: {
            displayName: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    const totalTips = tips.reduce((sum, tip) => sum + tip.amountCents, 0);
    const tipCount = tips.length;
    const averageTip = tipCount > 0 ? totalTips / tipCount : 0;

    return {
      totalTips,
      tipCount,
      averageTip,
      recentTips: tips.slice(0, 10), // Last 10 tips
    };
  }

  static async getUserTipHistory(userId: string) {
    if (!MONETIZATION_FEATURES.TIPS_ENABLED) {
      return [];
    }

    const tips = await prisma.balanceTransaction.findMany({
      where: {
        userId,
        type: 'TIP',
      },
      select: {
        id: true,
        amountCents: true,
        createdAt: true,
        metaJson: true,
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    return tips.map(tip => ({
      id: tip.id,
      amount: tip.amountCents,
      date: tip.createdAt,
      metadata: tip.metaJson,
    }));
  }
}
